        "f855a52e7f36429283fb7f5313b3edb4": {
          "id": "f855a52e7f36429283fb7f5313b3edb4",
          "name": "Get All User Badges",
          "script": "(function execute() {\n\n        vaInputs.user_badges_count = '';\n        var baseURL = gs.getProperty('glide.servlet.uri');\n        var images = {};\n        images['PERMANENT_BADGE'] = baseURL + '/x_aleen_aia_skills.permanentbadge.png';\n        images['TEMP_BADGE'] = baseURL + '/x_aleen_aia_skills.visitorbadge.png';\n        images['MOBILE_CREDENTIAL'] = baseURL + '/x_aleen_aia_skills.digitalbadge.png';\n\n        var identityId = vaInputs.user_sys_id;\n        var badgeAction = vaInputs.badge_action;\n        var badgeArray = [];\n\n        var badgeGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset');\n        badgeGr.addQuery('identity', identityId);\n        badgeGr.addNotNullQuery('status');\n        badgeGr.addQuery('is_deleted', false);\n        if (badgeAction == \"activate\") {\n           badgeGr.addQuery('status.code', 'INACTIVE');\n        } else {\n           badgeGr.addQuery('status.code', 'ACTIVE');\n        }\n        badgeGr.query();\n        while (badgeGr.next()) {\n        badgeArray.push({\n            'name': badgeGr.getDisplayValue(\"asset.serial\"),\n            'value': badgeGr.getValue(\"sys_id\"),\n            'description': badgeGr.getDisplayValue(\"identity.full_name\"),\n            'body': images[badgeGr.getDisplayValue(\"asset.type.code\")]\n        });\n        }\n        vaVars.user_badges = badgeArray;\n        if(badgeArray.length > 0) {\n           vaInputs.user_badges_count = badgeArray.length;\n        }\n\n       \n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
